import{_ as n,o as t,c as a,a3 as o}from"./chunks/framework.-MjGFDw0.js";const m=JSON.parse('{"title":"Veelgestelde vragen","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"nurse/faq.md","filePath":"nurse/faq.md","lastUpdated":1795769336000}'),r={name:"nurse/faq.md"};function i(d,e,s,l,p,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="veelgestelde-vragen" tabindex="-1">Veelgestelde vragen <a class="header-anchor" href="#veelgestelde-vragen" aria-label="Permalink to &quot;Veelgestelde vragen&quot;">​</a></h1><p>Vragen van softwarehuizen over het prestatiebestand, met het antwoord van TDM3.</p><h2 id="is-bezoeknummer-uniek-in-het-hele-bestand-of-per-patient" tabindex="-1">Is bezoeknummer uniek in het hele bestand, of per patiënt? <a class="header-anchor" href="#is-bezoeknummer-uniek-in-het-hele-bestand-of-per-patient" aria-label="Permalink to &quot;Is bezoeknummer uniek in het hele bestand, of per patiënt?&quot;">​</a></h2><p><em>Is <code>bezoeknummer</code> op uitgevoerdezorg het unieke nummer van het bezoek in het hele bestand, of is het uniek per patiënt (eerste, tweede, derde bezoek van die patiënt)?</em></p><p><code>bezoeknummer</code> is het volgnummer van het bezoek bij de patiënt op die dag, van 1 tot en met 10. Het is geen uniek id in het bestand.</p><ul><li>Alle zorgen van hetzelfde bezoek hebben hetzelfde nummer.</li><li>De <a href="/pr-preview/pr-13/nurse/nodes#node-lezingidentiteit">lezingidentiteit</a> wordt gekoppeld op patiënt, datum en bezoeknummer.</li><li>De volgorde van de basisverstrekkingen (eerste, tweede, derde) volgt het tijdstip in <code>datumuitvoering</code>, niet het bezoeknummer.</li></ul><h2 id="moet-ruraal-een-string-of-een-boolean-zijn" tabindex="-1">Moet ruraal een string of een boolean zijn? <a class="header-anchor" href="#moet-ruraal-een-string-of-een-boolean-zijn" aria-label="Permalink to &quot;Moet ruraal een string of een boolean zijn?&quot;">​</a></h2><p><em>In het XSD is <code>ruraal</code> op patientgegevens een xs:string en op adres een xs:boolean. Moeten ze allebei boolean zijn?</em></p><p>Het XSD is historisch gegroeid: <code>ruraal</code> is op patientgegevens een string en op adres een boolean. Vul op beide plaatsen <code>true</code> of <code>false</code> in.</p><p>Let op: de waarden <code>1</code>, <code>0</code> of een leeg veld worden gelezen als <code>false</code>. Zie ook <a href="/pr-preview/pr-13/nurse/nodes#toegestane-waarden">Toegestane waarden</a>.</p>',10)])])}const g=n(r,[["render",i]]);export{m as __pageData,g as default};
